{
  "headline": "Promethazine hydrochloride is not on FDA's shortage list; supply traces to a plant with a Warning Letter 2026-06-02 and another plant with multiple OAI inspections and Warning Letters",
  "headline_cites": ["D4", "E12", "E14", "E18", "E20", "E22", "E23", "E24"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows promethazine hydrochloride is not listed as of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "Corvale General holds two NDCs for 25 mg tablets: one from PD-Rx Pharmaceuticals, Inc. (NDC 43063040505) and one from Zydus Lifesciences Limited (NDC 65841004110).",
      "cites": ["E2", "E3"]
    },
    {
      "text": "The PD-Rx label names a registered plant (FEI 1641825) whose most recent inspection was classified VAI on 2026-08-20.",
      "cites": ["E8", "E7"]
    },
    {
      "text": "The Zydus label names a registered plant (FEI 3005430968) that received a Warning Letter on 2026-06-02.",
      "cites": ["E13", "E12"]
    },
    {
      "text": "A second Zydus plant (FEI 3002984011) has a history of OAI inspections on 2011-02-03, 2014-09-05, and 2019-05-03, with Warning Letters on 2011-06-21, 2015-12-23, and 2019-10-29.",
      "cites": ["E14", "E18", "E20", "E22", "E23", "E24"]
    },
    {
      "text": "The ranked transfer option moves 9 tablets of 25 mg from Corvale General (23 days on hand) to Corvale Lakeside (9.6 days on hand), leaving General with 22 days and bringing Lakeside to 14 days.",
      "cites": ["D5"]
    },
    {
      "text": "Check whether the Warning Letter at FEI 3005430968 and the OAI history at FEI 3002984011 affect current supply reliability for the Zydus NDC.",
      "cites": ["E12", "E14", "E18", "E20", "E22", "E23", "E24"]
    }
  ]
}
